1	/**
2	 * Nexus sidecar protocol v1: newline-delimited JSON between the Ratatui client (parent) and the
3	 * Node agent sidecar (child). The sidecar projects agent state; it never asks the client to decide outcomes.
4	 */
5	import type { ProviderRecoveryRecord, TurnResult } from "./core/turn.js";
6	import { redactSecrets, safeTerminal } from "./ui.js";
7	import { persistableEndpoint, scrubUrls } from "./core/endpoint_identity.js";
8	import type { ApprovalReview } from "./approval_review.js";
9	import type { SlashSpec } from "./slash/catalog.js";
10	import type { EvidenceStatus, ReceiptSection } from "./evidence.js";
11	import type { Catalog } from "./model_catalog.js";
12	
13	export const PROTOCOL_VERSION = 1;
14	/**
15	 * The inclusive range of protocol versions this sidecar can speak: `hello` announces it, `initialize` negotiates
16	 * inside it, and `parseCommand` accepts a message whose `v` lies in it. A version bump changes this pair (and
17	 * `PROTOCOL_VERSION`, the version the sidecar speaks by default) and nothing else in the negotiation.
18	 */
19	export const PROTOCOL_MIN = 1;
20	export const PROTOCOL_MAX = PROTOCOL_VERSION;
21	/** Largest protocol version number `initialize` accepts in a client's range (a bound on the field, not a version that exists). */
22	export const MAX_PROTOCOL_NUMBER = 65_535;
23	/** Longest `client.name` and `client.version` that `initialize` accepts. */
24	export const MAX_CLIENT_FIELD = 100;
25	
26	/**
27	 * Stable features of this sidecar, announced in `hello` and `initialized`. Each name is the `type` of a command a
28	 * client may send beyond the minimal set every sidecar handles (`prompt.submit`, `cancel`, `approve`, `deny`,
29	 * `shutdown`), so a client checks `capabilities.includes(type)` before it sends that command. Sorted; a name is
30	 * never removed or given a new meaning within a protocol version.
31	 */
32	export const SIDECAR_CAPABILITIES = [
33	  /** `answer`: the operator's decision on a question a turn ended BLOCKED / NEEDS_INPUT with. */
34	  "answer",
35	  /** `checkpoint.choice`: the answer to a `checkpoint.choice.request` event. */
36	  "checkpoint.choice",
37	  /** `model.select`: switch model between turns; answered with `model.result`. */
38	  "model.select",
39	  /** `models.list`: providers and models; answered with `models.catalog`. */
40	  "models.list",
41	  /** `provider.connect`, with `provider.cancel` and `provider.local-cancel` for the same request; answered with `provider.auth` and `provider.result`. */
42	  "provider.connect",
43	  /** `provider.disconnect`: answered with `provider.result`. */
44	  "provider.disconnect",
45	  /** `receipt`: the evidence receipt of the last turn; answered with the `receipt` event. */
46	  "receipt",
47	  /** `slash`: run a command of the catalogue `hello` carries; answered with `slash.result`. */
48	  "slash",
49	  /** `steer`: guidance for the work in progress; answered with `steer.ack`. */
50	  "steer",
51	  /** `tool.detail`: the full record of one tool call; answered with the `tool.detail` event. */
52	  "tool.detail",
53	] as const;
54	
55	/**
56	 * Experimental features this sidecar offers (none today). A new method sits here, refused with
57	 * `EXPERIMENTAL_DISABLED` unless the client sent `initialize` with `experimental: true`, until a conformance suite
58	 * has run against two real clients (docs/v1.3.0/PLAN.md, principle 8); then its name moves to SIDECAR_CAPABILITIES.
59	 */
60	export const EXPERIMENTAL_FEATURES: readonly string[] = [];
61	export const MAX_TEXT_FIELD = 8000;
62	/**
63	 * Longest clipboard text `/paste` puts into the composer, and the limit of the `slash.result` composer field. It keeps
64	 * the escaped `slash.result` line under the TUI's 1 MiB protocol line cap.
65	 */
66	export const MAX_PASTE = 100_000;
67	export const MAX_SUMMARY = 160;
68	export const MAX_SLASH_OUTPUT = 32_000;
69	
70	/**
71	 * `UNSUPPORTED_PROTOCOL`: `initialize` named a version range that shares no version with the sidecar's.
72	 * `EXPERIMENTAL_DISABLED`: an experimental feature was used on a connection that did not enable it at `initialize`.
73	 */
74	export type ErrorCode = "BAD_REQUEST" | "BUSY" | "NO_PENDING_APPROVAL" | "NOT_FOUND" | "INTERNAL" | "NO_PROVIDER" | "UNSUPPORTED_PROTOCOL" | "EXPERIMENTAL_DISABLED";
75	
76	/** Lines of a file diff shown in the transcript; the full diff is in the tool call's detail record. */
77	export const DIFF_PREVIEW_LINES = 40;
78	export const DIFF_PREVIEW_CHARS = 6000;
79	
80	/**
81	 * What became of operator steering sent while work was running. `queued`: held for the next step boundary.
82	 * `applied`: given to the agent (at a step boundary, or as a follow-up turn). `deferred`: the turn was finishing; it
83	 * starts a follow-up turn. `cancelled`: the turn ended first; `text` is returned to the operator. `rejected`: nothing
84	 * it could steer (a command is running); `text` is returned. `duplicate`: this id was already received. `held`: the
85	 * steering negates a requirement and waits for the operator's decision; the outcome follows as `applied` or `cancelled`.
86	 */
87	export type SteerStatus = "held" | "queued" | "applied" | "deferred" | "cancelled" | "rejected" | "duplicate";
88	
89	/** One entry of a resumed conversation: a message, a tool the agent called, or the last turn's outcome. */
90	export interface HistoryEntry {
91	  role: "user" | "assistant" | "steering" | "tool" | "outcome";
92	  text: string;
93	  tool?: string;
94	  heading?: string;
95	  turn?: TurnResult;
96	}
97	
98	export interface ModelSummary {
99	  summary: string;
100	  notes?: string;
101	}
102	
103	export type SidecarEvent =
104	  | {
105	      type: "hello";
106	      /** The version the sidecar speaks by default. */
107	      protocol: number;
108	      pid: number;
109	      commands: Array<Pick<SlashSpec, "name" | "usage" | "summary">>;
110	      /** The inclusive range of protocol versions this sidecar can speak. Absent from a sidecar older than capability negotiation: it speaks exactly `protocol`. */
111	      protocol_min?: number;
112	      protocol_max?: number;
113	      /** Stable features the sidecar supports (SIDECAR_CAPABILITIES), sorted. */
114	      capabilities?: string[];
115	      /** Experimental features the sidecar offers; each stays off until `initialize` asks with `experimental: true`. */
116	      experimental?: string[];
117	    }
118	  /**
119	   * Answer to `initialize`. `protocol`: the highest version both ranges contain. `experimental`: the experimental
120	   * features now enabled for this connection (empty unless the client asked for them).
121	   */
122	  | { type: "initialized"; id: string; protocol: number; capabilities: string[]; experimental: string[] }
123	  | {
124	      type: "session.state";
125	      workspace: string;
126	      workspace_name: string;
127	      model: string;
128	      mode: "auto" | "review" | "read-only";
129	      git: { branch: string; dirty: number } | null;
130	      busy: boolean;
131	      /** The id the session is saved under (shown so it can be resumed or referred to). */
132	      session?: string;
133	      /** The same facts the REPL /status reports (gate I-3). */
134	      read_only?: boolean;
135	      context_tokens?: number;
136	      context_limit?: number;
137	      endpoint_kind?: "local" | "cloud";
138	      posture?: {
139	        mode: "auto" | "review" | "read-only";
140	        sandbox: string;
141	        trusted: boolean;
142	      };
143	    }
144	  | { type: "assistant.delta"; turn_id: string; text: string }
145	  /** The provider's stream has sent nothing for `silent_secs` (`stalled`), or sent data again. */
146	  | { type: "stream.stall"; turn_id: string; stalled: boolean; silent_secs: number }
147	  /** What the running turn is doing; sent on every phase change, independent of model output. */
148	  | {
149	      type: "activity";
150	      turn_id: string;
151	      phase: string;
152	      step: number;
153	      segment: number;
154	      tool?: string;
155	      subject?: string;
156	      /** The turn's budget: total steps across segments, and the wall-clock limit in minutes (when continuation is on). */
157	      max_steps?: number;
158	      max_minutes?: number;
159	    }
160	  /** A file-edit tool changed a file: that operation's own diff (bounded preview; `evidence` opens the full one). */
161	  | {
162	      type: "file.diff";
163	      turn_id: string;
164	      call_id: string;
165	      evidence: string;
166	      path: string;
167	      kind: "added" | "modified" | "deleted";
168	      added: number;
169	      removed: number;
170	      preview: string;
171	      truncated: boolean;
172	      total_lines: number;
173	      /** Changed and context lines in the whole diff (what "N more lines" counts), and its hunks. */
174	      diff_lines: number;
175	      hunks: number;
176	      /** The complete diff on disk (redacted), kept for the session whatever the in-memory limits. */
177	      full_path?: string;
178	      note?: string;
179	    }
180	  | { type: "steer.ack"; id: string; status: SteerStatus; message: string; text?: string }
181	  | { type: "tool.start"; turn_id: string; call_id: string; tool: string; subject: string; evidence: string }
182	  | {
183	      type: "tool.end";
184	      turn_id: string;
185	      call_id: string;
186	      tool: string;
187	      success: boolean;
188	      summary: string;
189	      lines: number;
190	      evidence: string;
191	      /** Commands: the first lines of their output (stdout, then stderr), redacted, controls made visible. */
192	      preview?: string;
193	      exit_code?: number | null;
194	      duration_ms?: number;
195	      timed_out?: boolean;
196	      /** The operator declined the call at its approval prompt (never set for a policy refusal). The call did not run. */
197	      denied?: true;
198	    }
199	  | { type: "approval.request"; id: string; turn_id: string; tool: string; subject: string; preview: string; review: ApprovalReview }
200	  | { type: "checkpoint.choice.request"; id: string; turn_id: string; message: string }
201	  | { type: "turn.result"; turn_id: string; heading: string; line: string; turn: TurnResult; model_summary: ModelSummary | null; saved: boolean }
202	  | {
203	      type: "slash.result";
204	      id: string;
205	      command: string;
206	      success: boolean;
207	      output: string;
208	      /** "diff": colour unified-diff lines. */
209	      format?: "diff";
210	      /** Text for the client to put into the composer. */
211	      composer?: string;
212	      /** Text for the client to write to the terminal clipboard with OSC 52 (the client encodes it; at most OSC52_MAX_BYTES). */
213	      clipboard?: string;
214	      /** The command started a turn with this prompt; the turn's events follow under the same id. */
215	      prompt?: string;
216	    }
217	  /**
218	   * `key`: a later notice with the same key replaces this one on screen (a live status, not a log line).
219	   * `detail`: the raw cause, redacted, for the operator to inspect on request. Both are optional, so an older
220	   * client shows `text` as it always did.
221	   */
222	  | { type: "notice"; text: string; key?: string; detail?: string }
223	  /** A resumed session's recent conversation (user and assistant text only), oldest first; `total` counts all of it. */
224	  | { type: "history"; session: string; total: number; messages: HistoryEntry[] }
225	  | {
226	      type: "tool.detail";
227	      id: string;
228	      evidence: string;
229	      tool: string;
230	      subject: string;
231	      status: EvidenceStatus;
232	      args: string;
233	      output: string;
234	      duration_ms: number | null;
235	      /** Full unified diff of the change this call made, when it changed a file (at most MAX_DIFF_DETAIL chars). */
236	      diff?: string;
237	      /** Characters in the complete diff; more than `diff` holds when it was cut to the in-memory limit. */
238	      diff_chars?: number;
239	      /** The complete diff on disk. */
240	      diff_path?: string;
241	    }
242	  | { type: "receipt"; id: string; sections: ReceiptSection[] }
243	  | { type: "error"; id?: string; code: ErrorCode; message: string }
244	  /** Answer to models.list: providers (with connection source, never a credential), models, current and recent. */
245	  | ({ type: "models.catalog"; id: string } & Catalog)
246	  /** A sign-in needs the operator: open `url` (and type `user_code` for a device flow). */
247	  | { type: "provider.auth"; id: string; provider: string; url: string; user_code?: string; instructions: string }
248	  /** Outcome of provider.connect / provider.disconnect. */
249	  | { type: "provider.result"; id: string; provider: string; success: boolean; message: string }
250	  /** Outcome of model.select. */
251	  | { type: "model.result"; id: string; success: boolean; message: string };
252	
253	export type SidecarCommand =
254	  /**
255	   * Optional negotiation, answered with `initialized` (or `error` / `UNSUPPORTED_PROTOCOL` when the ranges share no
256	   * version). A client that never sends it gets the behaviour of protocol 1 as first published. `protocol_min` and
257	   * `protocol_max` (inclusive, given together) are the versions the client can speak; omitted, they are this
258	   * message's `v`. `experimental: true` enables the experimental features `hello` listed.
259	   */
260	  | { type: "initialize"; id: string; client: { name: string; version: string }; protocol_min?: number; protocol_max?: number; experimental?: boolean }
261	  | { type: "prompt.submit"; id: string; text: string }
262	  /** Operator guidance for the work in progress (see SteerStatus). */
263	  | { type: "steer"; id: string; text: string }
264	  | { type: "cancel" }
265	  | { type: "approve"; id: string; always: boolean }
266	  | { type: "deny"; id: string }
267	  /**
268	   * VC-9: the operator's decision on a question a turn ended BLOCKED / NEEDS_INPUT with (`turn.needsInput.id`), for a
269	   * client with no live approval prompt. It is recorded now and applied when the next turn reaches that decision.
270	   */
271	  | { type: "answer"; id: string; question: string; option: "approve" | "decline" }
272	  | { type: "checkpoint.choice"; id: string; choice: "read_only" | "without_checkpoint" | "retry" | "allow_sensitive" | "cancel" | "other" }
273	  | { type: "slash"; id: string; command: string; args: string }
274	  | { type: "tool.detail"; id: string; evidence: string }
275	  | { type: "receipt"; id: string }
276	  | { type: "models.list"; id: string }
277	  | { type: "model.select"; id: string; provider: string; model: string }
278	  /** `key` only for method "api-key"; it is never echoed back or logged. */
279	  | { type: "provider.connect"; id: string; provider: string; method: string; key?: string; endpoint?: string }
280	  | { type: "provider.cancel"; id: string }
281	  /** Clear a completed local endpoint setup associated with this exact provider.connect request. */
282	  | { type: "provider.local-cancel"; id: string }
283	  | { type: "provider.disconnect"; id: string; provider: string }
284	  | { type: "shutdown" };
285	
286	export class ProtocolError extends Error {
287	  constructor(message: string, public readonly id?: string) {
288	    super(message);
289	    this.name = "ProtocolError";
290	  }
291	}
292	
293	const LONE_SURROGATE = /[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/g;
294	
295	/** Truncation can split a surrogate pair; a lone surrogate would serialize as JSON the client cannot decode. */
296	export function encodeEvent(event: SidecarEvent): string {
297	  const wellFormed = (_key: string, value: unknown) => (typeof value === "string" ? value.replace(LONE_SURROGATE, "\uFFFD") : value);
298	  return JSON.stringify({ v: PROTOCOL_VERSION, ...event }, wellFormed) + "\n";
299	}
300	
301	export function parseCommand(line: string): SidecarCommand {
302	  let raw: unknown;
303	  try {
304	    raw = JSON.parse(line);
305	  } catch {
306	    throw new ProtocolError("line is not valid JSON");
307	  }
308	  if (!raw || typeof raw !== "object" || Array.isArray(raw)) throw new ProtocolError("message must be a JSON object");
309	  const msg = raw as Record<string, unknown>;
310	  const id = typeof msg.id === "string" && msg.id ? msg.id : undefined;
311	  const version = msg.v;
312	  if (typeof version !== "number" || !Number.isInteger(version) || version < PROTOCOL_MIN || version > PROTOCOL_MAX) {
313	    throw new ProtocolError(`unsupported protocol version: ${String(msg.v)}`, id);
314	  }
315	  const requireId = (type: string): string => {
316	    if (!id) throw new ProtocolError(`${type} requires id`);
317	    return id;
318	  };
319	  switch (msg.type) {
320	    case "initialize": {
321	      const requestId = requireId("initialize");
322	      const client = msg.client;
323	      if (!client || typeof client !== "object" || Array.isArray(client)) throw new ProtocolError("initialize requires client: { name, version }", requestId);
324	      const { name, version: clientVersion } = client as Record<string, unknown>;
325	      for (const [field, value] of [["name", name], ["version", clientVersion]] as const) {
326	        if (typeof value !== "string" || !value.trim()) throw new ProtocolError(`initialize requires client.${field}: a non-empty string`, requestId);
327	        if (value.length > MAX_CLIENT_FIELD) throw new ProtocolError(`initialize client.${field} is longer than ${MAX_CLIENT_FIELD} characters`, requestId);
328	      }
329	      const bound = (field: "protocol_min" | "protocol_max"): number | undefined => {
330	        const value = msg[field];
331	        if (value === undefined) return undefined;
332	        if (typeof value !== "number" || !Number.isInteger(value) || value < 1 || value > MAX_PROTOCOL_NUMBER) {
333	          throw new ProtocolError(`initialize ${field} must be an integer from 1 to ${MAX_PROTOCOL_NUMBER}`, requestId);
334	        }
335	        return value;
336	      };
337	      const min = bound("protocol_min");
338	      const max = bound("protocol_max");
339	      if ((min === undefined) !== (max === undefined)) throw new ProtocolError("initialize requires protocol_min and protocol_max together", requestId);
340	      if (min !== undefined && max !== undefined && min > max) throw new ProtocolError(`initialize protocol_min (${min}) is greater than protocol_max (${max})`, requestId);
341	      if (msg.experimental !== undefined && typeof msg.experimental !== "boolean") throw new ProtocolError("initialize experimental must be a boolean", requestId);
342	      // A client that names no range speaks the version it wrote this message in.
343	      return {
344	        type: "initialize", id: requestId, client: { name: name as string, version: clientVersion as string },
345	        protocol_min: min ?? version, protocol_max: max ?? version, experimental: msg.experimental === true,
346	      };
347	    }
348	    case "prompt.submit": {
349	      const requestId = requireId("prompt.submit");
350	      const text = msg.text;
351	      if (typeof text !== "string" || !text.trim()) throw new ProtocolError("prompt.submit requires non-empty text", requestId);
352	      return { type: "prompt.submit", id: requestId, text };
353	    }
354	    case "steer": {
355	      const requestId = requireId("steer");
356	      const text = msg.text;
357	      if (typeof text !== "string" || !text.trim()) throw new ProtocolError("steer requires non-empty text", requestId);
358	      return { type: "steer", id: requestId, text };
359	    }
360	    case "cancel":
361	      return { type: "cancel" };
362	    case "approve":
363	      return { type: "approve", id: requireId("approve"), always: msg.always === true };
364	    case "deny":
365	      return { type: "deny", id: requireId("deny") };
366	    case "answer": {
367	      const requestId = requireId("answer");
368	      if (typeof msg.question !== "string" || !/^[0-9a-f]{12}$/.test(msg.question)) throw new ProtocolError("answer requires question: the 12-character needsInput.id", requestId);
369	      if (msg.option !== "approve" && msg.option !== "decline") throw new ProtocolError("answer requires option: approve or decline", requestId);
370	      return { type: "answer", id: requestId, question: msg.question, option: msg.option };
371	    }
372	    case "checkpoint.choice": {
373	      const requestId = requireId("checkpoint.choice");
374	      const choices = ["read_only", "without_checkpoint", "retry", "allow_sensitive", "cancel", "other"] as const;
375	      if (!choices.includes(msg.choice as typeof choices[number])) throw new ProtocolError("checkpoint.choice requires a supported choice", requestId);
376	      return { type: "checkpoint.choice", id: requestId, choice: msg.choice as typeof choices[number] };
377	    }
378	    case "slash": {
379	      const requestId = requireId("slash");
380	      const command = msg.command;
381	      if (typeof command !== "string" || !command.trim()) throw new ProtocolError("slash requires command", requestId);
382	      return { type: "slash", id: requestId, command, args: typeof msg.args === "string" ? msg.args : "" };
383	    }
384	    case "tool.detail": {
385	      const requestId = requireId("tool.detail");
386	      const evidence = msg.evidence;
387	      if (typeof evidence !== "string" || !evidence) throw new ProtocolError("tool.detail requires evidence", requestId);
388	      return { type: "tool.detail", id: requestId, evidence };
389	    }
390	    case "receipt":
391	      return { type: "receipt", id: requireId("receipt") };
392	    case "models.list":
393	      return { type: "models.list", id: requireId("models.list") };
394	    case "model.select": {
395	      const requestId = requireId("model.select");
396	      if (typeof msg.provider !== "string" || !msg.provider || typeof msg.model !== "string" || !msg.model.trim()) {
397	        throw new ProtocolError("model.select requires provider and model", requestId);
398	      }
399	      return { type: "model.select", id: requestId, provider: msg.provider, model: msg.model };
400	    }
401	    case "provider.connect": {
402	      const requestId = requireId("provider.connect");
403	      if (typeof msg.provider !== "string" || !msg.provider || typeof msg.method !== "string" || !msg.method) {
404	        throw new ProtocolError("provider.connect requires provider and method", requestId);
405	      }
406	      if (msg.key !== undefined && typeof msg.key !== "string") throw new ProtocolError("provider.connect key must be a string", requestId);
407	      if (msg.endpoint !== undefined && (typeof msg.endpoint !== "string" || !msg.endpoint || msg.endpoint.length > 2048 || /[\r\n\0]/.test(msg.endpoint))) {
408	        throw new ProtocolError("provider.connect endpoint must be a valid single-line URL", requestId);
409	      }
410	      return {
411	        type: "provider.connect", id: requestId, provider: msg.provider, method: msg.method,
412	        ...(typeof msg.key === "string" ? { key: msg.key } : {}),
413	        ...(typeof msg.endpoint === "string" ? { endpoint: msg.endpoint } : {}),
414	      };
415	    }
416	    case "provider.cancel":
417	      return { type: "provider.cancel", id: requireId("provider.cancel") };
418	    case "provider.local-cancel":
419	      return { type: "provider.local-cancel", id: requireId("provider.local-cancel") };
420	    case "provider.disconnect": {
421	      const requestId = requireId("provider.disconnect");
422	      if (typeof msg.provider !== "string" || !msg.provider) throw new ProtocolError("provider.disconnect requires provider", requestId);
423	      return { type: "provider.disconnect", id: requestId, provider: msg.provider };
424	    }
425	    case "shutdown":
426	      return { type: "shutdown" };
427	    default:
428	      throw new ProtocolError(`unknown message type: ${String(msg.type)}`, id);
429	  }
430	}
431	
432	export function capText(text: string, max: number = MAX_TEXT_FIELD): string {
433	  if (text.length <= max) return text;
434	  return `${text.slice(0, max)}…[truncated ${text.length - max} chars]`;
435	}
436	
437	/** CSI sequences, OSC sequences (BEL or ST terminated), then the remaining two-character escapes. */
438	const TERMINAL_ESCAPE = /\x1b\[[0-9;?]*[ -/]*[@-~]|\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)|\x1b[ -/]*[0-~]/g;
439	
440	export function stripEscapes(text: string): string {
441	  return text.replace(TERMINAL_ESCAPE, "");
442	}
443	
444	/** Secrets redacted from text with terminal escape sequences removed: the shared first step of every operator-facing one-line projection. */
445	export function redactPlain(text: string): string {
446	  return redactSecrets(stripEscapes(text));
447	}
448	
449	/** Operator-supplied text as shown to an operator or written to a record: escapes and control characters gone, secrets redacted, one line, capped. */
450	export function safeOperatorText(text: string, max = 300): string {
451	  return redactSecrets(stripEscapes(String(text)).replace(/[\x00-\x1f\x7f-\x9f]+/g, " ")).replace(/\s+/g, " ").trim().slice(0, max);
452	}
453	
454	export function toolSubject(args: Record<string, any>, tool?: string): string {
455	  if (tool === "steering_conflict" && Array.isArray(args.negates)) {
456	    const ids = args.negates.map((n: any) => safeOperatorText(String(n?.id ?? ""), 12)).join(", ");
457	    return safeOperatorText(`steering ${args.steering} negates ${ids}: ${args.text}`, 200);
458	  }
459	  const subject = args.path ?? args.file_path ?? args.command ?? args.url ?? args.query ?? args.name ?? "";
460	  return redactPlain(String(subject)).replace(/\s+/g, " ").trim().slice(0, 200);
461	}
462	
463	/** Copy of a turn with secrets redacted from its free-text fields; enums, counts, ids and hashes are left as-is. */
464	export function projectTurn(turn: TurnResult): TurnResult {
465	  const redactOptional = (text: string | undefined) => (text === undefined ? undefined : redactSecrets(text));
466	  return {
467	    ...turn,
468	    detail: redactOptional(turn.detail),
469	    verification: turn.verification ? { ...turn.verification, command: redactOptional(turn.verification.command) } : null,
470	    interruption: turn.interruption ? { ...turn.interruption, outstandingTool: redactOptional(turn.interruption.outstandingTool) } : null,
471	    inferenceFailure: turn.inferenceFailure ? { ...turn.inferenceFailure, message: redactSecrets(turn.inferenceFailure.message) } : null,
472	    ...(turn.convergence
473	      ? {
474	          convergence: {
475	            ...turn.convergence,
476	            evidence: redactSecrets(turn.convergence.evidence),
477	            attempts: turn.convergence.attempts.map((a) => ({
478	              ...a,
479	              command: redactSecrets(a.command),
480	              ...(a.failedCheck ? { failedCheck: redactSecrets(a.failedCheck) } : {}),
481	              ...(a.failingTests ? { failingTests: a.failingTests.map((t) => redactSecrets(t)) } : {}),
482	            })),
483	          },
484	        }
485	      : {}),
486	    ...(turn.turnEvidence
487	      ? { turnEvidence: { ...turn.turnEvidence, verifierRuns: turn.turnEvidence.verifierRuns.map((r) => ({ ...r, command: redactSecrets(r.command) })) } }
488	      : {}),
489	    ...(turn.providerRecovery
490	      ? {
491	          providerRecovery: turn.providerRecovery.map((r) => ({
492	            ...r,
493	            reason: redactOptional(r.reason),
494	            submissions: r.submissions.map((s) => ({ ...s, message: redactSecrets(s.message) })),
495	          })),
496	        }
497	      : {}),
498	  };
499	}
500	
501	/** The notice key of every provider-wait line: one live row that each transition replaces. */
502	export const PROVIDER_STATUS_KEY = "provider.recovery";
503	export const STARTUP_PROVIDER_KEY = "provider.startup";
504	
505	export interface StatusNotice {
506	  text: string;
507	  key: string;
508	  /** The raw cause (redacted); never part of `text`. */
509	  detail?: string;
510	}
511	
512	/** What went wrong, in words an operator can act on. */
513	function providerProblemWords(record: ProviderRecoveryRecord): string {
514	  const last = record.submissions[record.submissions.length - 1];
515	  const status = last?.httpStatus;
516	  if (record.condition === "AUTH_FAILURE" || status === 401 || status === 403) return "the provider rejected the credentials";
517	  if (record.condition === "QUOTA_EXHAUSTED" || status === 402) return "the provider account is out of quota";
518	  if (record.condition === "RATE_LIMITED" || status === 429) return "the provider is rate limiting requests";
519	  if (record.condition === "OVERLOADED" || status === 503 || status === 529) return "the provider is overloaded";
520	  if (record.condition === "DRAINING") return "the provider is restarting";
521	  if (last?.kind === "timeout") return "the provider did not answer in time";
522	  if (last?.kind === "network_error" || record.condition === "TEMPORARILY_UNAVAILABLE") return "the provider cannot be reached";
523	  return "the provider returned an error";
524	}
525	
526	function minutesWords(ms: number): string {
527	  const minutes = Math.round(ms / 60_000);
528	  return minutes < 1 ? "under a minute" : `about ${minutes} min`;
529	}
530	
531	function rawProviderCause(record: ProviderRecoveryRecord): string {
532	  const last = record.submissions[record.submissions.length - 1];
533	  const parts = [
534	    `condition ${record.condition}${last?.httpStatus ? `, HTTP ${last.httpStatus}` : ""}${last ? `, ${last.kind}, execution ${last.execution}` : ""}`,
535	    last?.message,
536	    record.reason ? `recovery: ${record.reason}` : undefined,
537	    last?.requestId ? `request ${last.requestId}` : undefined,
538	  ];
539	  return redactSecrets(scrubUrls(parts.filter(Boolean).join("\n")));
540	}
541	
542	/**
543	 * The provider-wait status line for one recovery transition (PROBING produces none). Every transition carries the
544	 * same `key`, so the client shows one row that changes instead of a line per attempt (D-06).
545	 */
546	export function providerRecoveryStatus(record: ProviderRecoveryRecord, discardedPartialOutput: boolean): StatusNotice | undefined {
547	  if (record.state === "PROBING") return undefined;
548	  const detail = rawProviderCause(record);
549	  const where = record.endpoint ? ` at ${persistableEndpoint(record.endpoint)}` : "";
550	  const problem = providerProblemWords(record);
551	  switch (record.state) {
552	    case "WAITING": {
553	      const secs = record.nextAttemptAt ? Math.max(0, Math.round((Date.parse(record.nextAttemptAt) - Date.parse(record.updatedAt)) / 1000)) : 0;
554	      const left = minutesWords(Math.max(0, record.policy.deadlineMs - record.waitedMs));
555	      const discarded = discardedPartialOutput ? " The partial response was discarded." : "";
556	      const text = `Waiting for the model provider${where}: ${problem}. Retry ${record.submissions.length}, next attempt in ${secs}s; gives up in ${left}. Your work is kept. /details shows the raw error; esc cancels.${discarded}`;
557	      return { text: redactSecrets(text), key: PROVIDER_STATUS_KEY, detail };
558	    }
559	    case "RESUMED":
560	      return { text: `The model provider recovered after ${Math.round(record.waitedMs / 1000)}s; step ${record.step} resumed.`, key: PROVIDER_STATUS_KEY, detail: `Recovered; the earlier error was:\n${detail}` };
561	    case "CANCELLED":
562	      return { text: "Stopped waiting for the model provider.", key: PROVIDER_STATUS_KEY, detail };
563	    default:
564	      return {
565	        text: redactSecrets(`Nexus stopped retrying the model provider${where}: ${problem}. Check the connection or use /connect, then send your message again. /details shows the raw error.`),
566	        key: PROVIDER_STATUS_KEY,
567	        detail,
568	      };
569	  }
570	}
571	
572	/** The answer to a prompt sent while the provider is still down: short, because the start-up notice already gave the steps. */
573	export function noProviderRefusal(problem: { endpoint: string; endpoints?: string[]; nothingThere?: boolean }): string {
574	  const named = problem.endpoints?.join(", ") ?? problem.endpoint;
575	  const why = problem.nothingThere === false ? `could not connect to ${named}` : `nothing answers at ${named}`;
576	  return redactSecrets(`Not sent: no model is connected (${why}). Use /connect or start a local model server, then send it again.`);
577	}
578	
579	/** First run with nothing to talk to: what is missing, what to do next, where to read more. The raw cause goes in `detail`. */
580	export function noProviderNotice(problem: { kind: "unreachable" | "rejected"; endpoint: string; endpoints?: string[]; detail: string; blocking?: boolean; nothingThere?: boolean }): StatusNotice {
581	  if (problem.kind === "rejected" || problem.blocking === false) {
582	    // Only a warning: the start-up check can be refused where chat is not (a token not yet refreshed, a key limited to chat).
583	    // With several endpoints that failed, each is named and the wording does not say how each failed (the detail does).
584	    const many = (problem.endpoints?.length ?? 0) > 1;
585	    const verb = many ? "did not pass" : problem.kind === "rejected" ? "rejected the credentials on" : "did not answer";
586	    return {
587	      text: redactSecrets(
588	        `${many ? problem.endpoints!.join(", ") : problem.endpoint} ${verb} the start-up check. Nexus will still try your messages; ` +
589	          `if they fail, type /connect to sign in again or check the API key and the server. \`nexus doctor\` checks the setup.`,
590	      ),
591	      key: STARTUP_PROVIDER_KEY,
592	      detail: redactSecrets(problem.detail),
593	    };
594	  }
595	  const named = problem.endpoints?.join(", ") ?? problem.endpoint;
596	  const missing = problem.nothingThere === false ? `No model is connected: Nexus could not connect to ${named}.` : `No model is connected: nothing answers at ${named}.`;
597	  const text =
598	    `${missing} Next: type /connect to sign in or add an API key, or start a local model server (LM Studio, Ollama, llama.cpp) ` +
599	    `and send your message again. \`nexus doctor\` checks the setup; docs/CLOUD_PROVIDERS.md lists providers.`;
600	  return { text: redactSecrets(text), key: STARTUP_PROVIDER_KEY, detail: redactSecrets(problem.detail) };
601	}
602	
603	/** Lines of a command's output carried in `tool.end` for the transcript preview. */
604	export const TOOL_PREVIEW_LINES = 8;
605	
606	export interface ToolSummary {
607	  summary: string;
608	  lines: number;
609	  preview?: string;
610	  exit_code?: number | null;
611	  duration_ms?: number;
612	  timed_out?: boolean;
613	}
614	
615	/**
616	 * What the transcript shows for a finished tool. A command's JSON result (`stdout`, `stderr`, `exit_code`) becomes a
617	 * real summary (`exit 0 · 122 lines`, or `no output`), the count of its output lines and a bounded preview of them;
618	 * other tools keep the first line of their output (or error) as the summary.
619	 */
620	export function toolSummary(success: boolean, output: string, error?: string): ToolSummary {
621	  const command = commandResult(output);
622	  if (command) {
623	    const body = [command.stdout.trimEnd(), command.stderr.trimEnd()].filter(Boolean).join("\n");
624	    const rows = body ? body.split(/\r?\n/) : [];
625	    const exit = command.timed_out ? "timed out" : command.exit_code === null ? "no exit code" : `exit ${command.exit_code}`;
626	    const failure = success ? "" : (error ?? "").split(/\r?\n/).find((line) => line.trim())?.trim() ?? "";
627	    const summary = failure && !failure.startsWith("{") ? failure : `${exit} · ${rows.length ? `${rows.length} line${rows.length === 1 ? "" : "s"}` : "no output"}`;
628	    return {
629	      summary: redactPlain(summary).replace(/\s+/g, " ").slice(0, MAX_SUMMARY),
630	      lines: rows.length,
631	      preview: (rows.length > TOOL_PREVIEW_LINES ? rows.slice(-TOOL_PREVIEW_LINES) : rows).map((row) => safeTerminal(row).slice(0, 400)).join("\n"),
632	      exit_code: command.exit_code,
633	      ...(command.duration_ms !== undefined ? { duration_ms: command.duration_ms } : {}),
634	      ...(command.timed_out ? { timed_out: true } : {}),
635	    };
636	  }
637	  const text = redactPlain(success ? output || "" : error || output || "").trim();
638	  const first = text.split(/\r?\n/).find((line) => line.trim())?.trim() ?? (success ? "Completed" : "Tool failed");
639	  return { summary: first.replace(/\s+/g, " ").slice(0, MAX_SUMMARY), lines: text ? text.split(/\r?\n/).length : 0 };
640	}
641	
642	/** The structured result of a shell command tool, when `output` is one. */
643	function commandResult(output: string): { stdout: string; stderr: string; exit_code: number | null; duration_ms?: number; timed_out?: boolean } | undefined {
644	  if (!output || output.trimStart()[0] !== "{") return undefined;
645	  try {
646	    const parsed = JSON.parse(output);
647	    if (parsed && typeof parsed === "object" && typeof parsed.stdout === "string" && "exit_code" in parsed) {
648	      return {
649	        stdout: parsed.stdout,
650	        stderr: typeof parsed.stderr === "string" ? parsed.stderr : "",
651	        exit_code: typeof parsed.exit_code === "number" ? parsed.exit_code : null,
652	        ...(typeof parsed.duration_ms === "number" ? { duration_ms: parsed.duration_ms } : {}),
653	        ...(parsed.timed_out === true ? { timed_out: true } : {}),
654	      };
655	    }
656	  } catch {}
657	  return undefined;
658	}
