216	async function withSidecar(fn: (rig: Rig) => Promise<void>, options: Partial<SidecarOptions> = {}, script: (n: number) => Reply = () => ({ kind: "text", content: "Done." })): Promise<void> {
217	  const gw = await startGateway(script);
