370	// A small JSON Schema validator for the subset scripts/gen_protocol_schema.mjs emits (draft 2020-12 keywords: type,
371	// const, enum, properties, required, additionalProperties, items, prefixItems, minItems, maxItems, anyOf, oneOf and a
372	// local $ref). It is a test helper, not a general validator: a keyword outside that subset throws, so a generator that
373	// starts emitting a new keyword cannot pass unvalidated.
374	import { isDeepStrictEqual } from "node:util";
375	
376	export type Schema = Record<string, any>;
377	
378	const ANNOTATIONS = new Set(["$schema", "$defs", "title", "description"]);
379	const KEYWORDS = new Set(["$ref", "type", "const", "enum", "properties", "required", "additionalProperties", "items", "prefixItems", "minItems", "maxItems", "anyOf", "oneOf"]);
380	
381	function typeName(value: unknown): string {
382	  if (value === null) return "null";
383	  if (Array.isArray(value)) return "array";
384	  return typeof value;
385	}
386	
387	function resolve(root: Schema, ref: string): Schema {
388	  if (!ref.startsWith("#/")) throw new Error(`unsupported $ref: ${ref}`);
389	  let node: any = root;
390	  for (const part of ref.slice(2).split("/")) node = node?.[part.replace(/~1/g, "/").replace(/~0/g, "~")];
391	  if (!node || typeof node !== "object") throw new Error(`unresolved $ref: ${ref}`);
392	  return node;
393	}
394	
395	/** Every way `value` fails `schema`, as `path: reason` lines; empty when it is valid. `root` resolves `$ref`. */
396	export function validate(value: unknown, schema: Schema, root: Schema = schema, at = "$"): string[] {
397	  for (const keyword of Object.keys(schema)) {
398	    if (!KEYWORDS.has(keyword) && !ANNOTATIONS.has(keyword)) throw new Error(`unsupported schema keyword at ${at}: ${keyword}`);
399	  }
400	  const errors: string[] = [];
401	  if (schema.$ref) errors.push(...validate(value, resolve(root, schema.$ref), root, at));
402	  const actual = typeName(value);
403	  if (schema.type !== undefined && actual !== schema.type) errors.push(`${at}: expected ${schema.type}, got ${actual}`);
404	  if ("const" in schema && !isDeepStrictEqual(value, schema.const)) errors.push(`${at}: expected ${JSON.stringify(schema.const)}`);
405	  if (schema.enum && !schema.enum.some((allowed: unknown) => isDeepStrictEqual(value, allowed))) errors.push(`${at}: not one of ${JSON.stringify(schema.enum)}`);
406	
407	  if (actual === "object") {
408	    const object = value as Record<string, unknown>;
409	    const properties: Record<string, Schema> = schema.properties ?? {};
410	    for (const name of schema.required ?? []) {
411	      if (!Object.hasOwn(object, name)) errors.push(`${at}: missing required ${name}`);
412	    }
413	    for (const [name, member] of Object.entries(object)) {
414	      if (Object.hasOwn(properties, name)) errors.push(...validate(member, properties[name], root, `${at}.${name}`));
415	      else if (schema.additionalProperties === false) errors.push(`${at}: unexpected property ${name}`);
416	      else if (typeof schema.additionalProperties === "object") errors.push(...validate(member, schema.additionalProperties, root, `${at}.${name}`));
417	    }
418	  }
419	
420	  if (actual === "array") {
421	    const array = value as unknown[];
422	    const prefix: Schema[] = schema.prefixItems ?? [];
423	    if (schema.minItems !== undefined && array.length < schema.minItems) errors.push(`${at}: fewer than ${schema.minItems} items`);
424	    if (schema.maxItems !== undefined && array.length > schema.maxItems) errors.push(`${at}: more than ${schema.maxItems} items`);
425	    array.forEach((item, i) => {
426	      if (i < prefix.length) errors.push(...validate(item, prefix[i], root, `${at}[${i}]`));
427	      else if (schema.items) errors.push(...validate(item, schema.items, root, `${at}[${i}]`));
428	    });
429	  }
430	
431	  for (const keyword of ["anyOf", "oneOf"] as const) {
432	    if (!schema[keyword]) continue;
433	    const results: string[][] = schema[keyword].map((option: Schema) => validate(value, option, root, at));
434	    const matches = results.filter((result) => result.length === 0).length;
435	    if (matches === 1 || (matches > 1 && keyword === "anyOf")) continue;
436	    if (matches > 1) {
437	      errors.push(`${at}: matches ${matches} oneOf alternatives`);
438	      continue;
439	    }
440	    // Explain with the alternative that came closest. For a message union that is the variant whose `type` matched;
441	    // when no variant's did, the type is unknown and there is nothing more to say.
442	    const candidates = results.filter((result) => !result.some((error) => error.startsWith(`${at}.type:`)));
443	    const closest = candidates.reduce<string[]>((best, result) => (best.length === 0 || result.length < best.length ? result : best), []);
444	    errors.push(`${at}: matches no ${keyword} alternative`, ...closest);
445	  }
446	  return errors;
447	}
448	// Transparent sidecar shim for `nexus-tui --live --sidecar <this file>`: runs the real sidecar named by
449	// NEXUS_RECORD_SIDECAR and appends every raw stdin chunk to NEXUS_RECORD_COMMANDS and every raw stdout chunk to
450	// NEXUS_RECORD_EVENTS. It never parses, filters or rewrites bytes. Appends are synchronous so both logs are
451	// complete when the process exits.
452	import { spawn } from "node:child_process";
453	import fs from "node:fs";
454	
455	const commandsLog = process.env.NEXUS_RECORD_COMMANDS;
456	const eventsLog = process.env.NEXUS_RECORD_EVENTS;
457	
458	const child = spawn(process.execPath, [process.env.NEXUS_RECORD_SIDECAR, ...process.argv.slice(2)], {
459	  stdio: ["pipe", "pipe", "inherit"],
460	});
461	
462	process.stdin.on("data", (chunk) => {
463	  fs.appendFileSync(commandsLog, chunk);
464	  child.stdin.write(chunk);
465	});
466	process.stdin.on("end", () => child.stdin.end());
467	child.stdin.on("error", () => {});
468	process.stdout.on("error", () => {});
469	
470	child.stdout.on("data", (chunk) => {
471	  fs.appendFileSync(eventsLog, chunk);
472	  process.stdout.write(chunk);
473	});
474	
475	for (const signal of ["SIGTERM", "SIGINT", "SIGHUP"]) {
476	  process.on(signal, () => child.kill(signal));
477	}
478	
479	child.on("close", (code) => {
480	  process.exit(code ?? 1);
481	});
