500	{"direction":"command","name":"receipt","json":"{\"v\":1,\"type\":\"receipt\",\"id\":\"r1\"}"}
501	{"direction":"command","name":"shutdown","json":"{\"v\":1,\"type\":\"shutdown\"}"}
502	{"direction":"event","name":"hello","json":"{\"v\":1,\"type\":\"hello\",\"protocol\":1,\"pid\":42,\"commands\":[{\"name\":\"help\",\"usage\":\"/help\",\"summary\":\"Show help\"}],\"protocol_min\":1,\"protocol_max\":1,\"capabilities\":[\"answer\",\"checkpoint.choice\",\"model.select\",\"models.list\",\"provider.connect\",\"provider.disconnect\",\"receipt\",\"slash\",\"steer\",\"tool.detail\"],\"experimental\":[\"x.test\"]}"}
503	{"direction":"event","name":"initialized","json":"{\"v\":1,\"type\":\"initialized\",\"id\":\"i1\",\"protocol\":1,\"capabilities\":[\"answer\",\"checkpoint.choice\",\"model.select\",\"models.list\",\"provider.connect\",\"provider.disconnect\",\"receipt\",\"slash\",\"steer\",\"tool.detail\"],\"experimental\":[]}"}
504	{"direction":"command","name":"initialize","json":"{\"v\":1,\"type\":\"initialize\",\"id\":\"i1\",\"client\":{\"name\":\"nexus-tui\",\"version\":\"1.3.0\"},\"protocol_min\":1,\"protocol_max\":1,\"experimental\":false}"}
505	// Generates the JSON Schema (draft 2020-12) of the sidecar wire protocol from the types in src/protocol.ts, using the
506	// TypeScript 7 type checker (`typescript/unstable/sync`, which drives the bundled tsgo binary). The output is
507	// deterministic: definitions, properties, required lists, enum members and message variants are sorted, and nothing
508	// from the host (paths, time) is written, so the checked-in copy can be compared byte for byte.
509	//
510	//   node scripts/gen_protocol_schema.mjs           write docs/protocol/sidecar-v<N>.schema.json
511	//   node scripts/gen_protocol_schema.mjs --check   exit 1 when the checked-in schema or the version ledger is stale
512	//
513	// A type this file cannot express (a function-typed property, a tuple with optional or rest elements, a template literal, ...) is an error, never a
514	// silent `{}`: extend the generator deliberately. Only `any` and `unknown` become the open schema `{}`.
515	import crypto from "node:crypto";
516	import fs from "node:fs";
517	import path from "node:path";
518	import { fileURLToPath } from "node:url";
519	import { API, ElementFlags, SignatureKind, SymbolFlags, TypeFlags } from "typescript/unstable/sync";
520	
521	const cli = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
522	const repo = path.resolve(cli, "..");
523	const sourceDir = path.join(cli, "src") + path.sep;
524	const protocolSource = path.join(cli, "src", "protocol.ts");
525	
526	export const LEDGER_FILE = path.join(repo, "docs", "protocol", "VERSIONS.json");
527	export const schemaFile = (version) => path.join(repo, "docs", "protocol", `sidecar-v${version}.schema.json`);
528	export const sha256 = (text) => crypto.createHash("sha256").update(text).digest("hex");
529	
530	const byText = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
531	
532	class SchemaBuilder {
533	  constructor(checker) {
534	    this.checker = checker;
535	    this.defs = {};
536	    this.defOwners = new Map();
537	  }
538	
539	  fail(type, where, why) {
540	    throw new Error(`gen_protocol_schema: ${where}: ${why} (${this.checker.typeToString(type)})`);
541	  }
542	
543	  /** The symbol that names `type` when it is an alias, interface or class declared under cli/src; otherwise it is inlined. */
544	  nameOf(type) {
545	    const alias = type.getAliasSymbol();
546	    let symbol;
547	    if (alias) {
548	      // An instantiated generic alias (Pick<...>, Record<...>) has no single shape to publish under its name.
549	      if (type.getAliasTypeArguments().length) return undefined;
550	      symbol = alias;
551	    } else if (type.isClassOrInterface()) {
552	      if (type.getTypeParameters().length) return undefined;
553	      symbol = type.getSymbol();
554	    }
555	    const declared = symbol?.declarations[0]?.path;
556	    return declared && declared.startsWith(sourceDir) ? symbol : undefined;
557	  }
558	
559	  schemaOf(type, where) {
560	    const symbol = this.nameOf(type);
561	    if (!symbol) return this.structureOf(type, where);
562	    const name = symbol.name;
563	    const owner = this.defOwners.get(name);
564	    if (owner === undefined) {
565	      this.defOwners.set(name, symbol.id);
566	      this.defs[name] = {}; // reserved first, so a self-referencing type terminates
567	      const description = symbol.getDocumentationComment(this.checker);
568	      this.defs[name] = { ...(description ? { description } : {}), ...this.structureOf(type, name) };
569	    } else if (owner !== symbol.id) {
570	      this.fail(type, where, `two different types are both named ${name}`);
571	    }
572	    return { $ref: `#/$defs/${name}` };
573	  }
574	
575	  structureOf(type, where) {
576	    const flags = type.flags;
577	    if (flags & TypeFlags.AnyOrUnknown) return {};
578	    if (flags & TypeFlags.Boolean) return { type: "boolean" };
579	    if (flags & TypeFlags.String) return { type: "string" };
580	    if (flags & TypeFlags.Number) return { type: "number" };
581	    if (flags & TypeFlags.Null) return { type: "null" };
582	    if (flags & TypeFlags.EnumLike) this.fail(type, where, "enum types are not supported");
583	    if (flags & (TypeFlags.StringLiteral | TypeFlags.NumberLiteral | TypeFlags.BooleanLiteral)) return { const: type.value };
584	    if (type.isUnionType()) return this.unionOf(type, where);
585

