import { test } from "node:test";
import * as assert from "node:assert/strict";
import fs from "node:fs";
import { fileURLToPath } from "node:url";
import { EXPERIMENTAL_FEATURES, PROTOCOL_MAX, PROTOCOL_MIN, PROTOCOL_VERSION, SIDECAR_CAPABILITIES } from "../src/protocol.js";
import { generateProtocolSchema, ledgerProblem, LEDGER_FILE, schemaFile, sha256 } from "../scripts/gen_protocol_schema.mjs";
import { validate, type Schema } from "./helpers/json_schema.js";

// The published schema (docs/protocol) is generated from src/protocol.ts. These tests fail when a protocol type changes
// without the schema being regenerated and the version decision being recorded in the ledger.
const generated = generateProtocolSchema();
const checkedIn = fs.readFileSync(schemaFile(PROTOCOL_VERSION), "utf8");
const schema: Schema = JSON.parse(checkedIn);
const direction = { event: { $ref: "#/$defs/SidecarEvent" }, command: { $ref: "#/$defs/SidecarCommand" } };
const check = (message: unknown, to: keyof typeof direction) => validate(message, direction[to], schema);
const variantTypes = (name: "SidecarEvent" | "SidecarCommand"): string[] => schema.$defs[name].oneOf.map((variant: Schema) => variant.properties.type.const);

test("the checked-in protocol schema equals a fresh generation from src/protocol.ts", () => {
  assert.equal(generated.version, PROTOCOL_VERSION);
  assert.equal(
    checkedIn,
    generated.text,
    "docs/protocol schema is out of date: run `node cli/scripts/gen_protocol_schema.mjs`, then record the version decision in docs/protocol/VERSIONS.json",
  );
});

test("the newest version-ledger entry records the current schema and protocol version", () => {
  const ledger = JSON.parse(fs.readFileSync(LEDGER_FILE, "utf8"));
  assert.equal(ledgerProblem(checkedIn, ledger, PROTOCOL_VERSION), undefined);
  for (const entry of ledger) {
    assert.ok(Number.isInteger(entry.protocol) && /^[0-9a-f]{64}$/.test(entry.schemaSha256) && typeof entry.note === "string" && entry.note.trim(), "each entry has protocol, schemaSha256 and a note");
  }
  // The rule itself: a changed schema, or a version bump, without a new entry is a failure.
  assert.match(ledgerProblem(`${checkedIn} `, ledger, PROTOCOL_VERSION) ?? "", /add an entry/);
  assert.match(ledgerProblem(checkedIn, ledger, PROTOCOL_VERSION + 1) ?? "", /PROTOCOL_VERSION is/);
  assert.match(ledgerProblem(checkedIn, [], PROTOCOL_VERSION) ?? "", /no entries/);
  assert.equal(ledger[ledger.length - 1].schemaSha256, sha256(checkedIn));
});

// Golden records that predate a field the type now requires. The Rust client still accepts them (older sidecars), so
// they stay in the corpus; each must fail for exactly the reason listed, so this list can only shrink.
const GOLDEN_MISSING_REQUIRED: Record<string, string[]> = {
  hello: ["$: missing required commands"],
  "tool.end": ["$: missing required evidence"],
};

test("every golden corpus record validates against the schema for its direction", () => {
  const corpus = fileURLToPath(new URL("./fixtures/protocol_v1_golden.jsonl", import.meta.url));
  const records = fs.readFileSync(corpus, "utf8").split(/\r?\n/).filter(Boolean).map((line) => JSON.parse(line));
  assert.ok(records.length >= 8);
  const exceptions = new Set(Object.keys(GOLDEN_MISSING_REQUIRED));
  for (const record of records) {
    const message = JSON.parse(record.json);
    const errors = check(message, record.direction);
    // A later record of the same name that carries the field (the hello with the negotiation fields) is not a gap.
    const gaps = record.direction === "event" ? (GOLDEN_MISSING_REQUIRED[record.name] ?? []).filter((gap) => !(gap.replace("$: missing required ", "") in message)) : [];
    const expected = gaps.length ? gaps : undefined;
    if (expected) {
      exceptions.delete(record.name);
      assert.deepEqual(errors.filter((error) => !error.includes("oneOf alternative")), expected, `${record.name}: known gap`);
    } else {
      assert.deepEqual(errors, [], `${record.direction} ${record.name}`);
    }
  }
  assert.deepEqual([...exceptions], [], "a listed exception has no golden record");
});

test("messages built to the current types validate", () => {
  assert.deepEqual(check({ v: 1, type: "hello", protocol: 1, pid: 42, commands: [{ name: "help", usage: "/help", summary: "Show help" }] }, "event"), []);
  assert.deepEqual(check({ v: 1, type: "tool.end", turn_id: "t1", call_id: "c1", tool: "run_command", success: true, summary: "ok", lines: 1, evidence: "e1", exit_code: null }, "event"), []);
  assert.deepEqual(check({ v: 1, type: "receipt", id: "r1", sections: [{ title: "Last turn", rows: [["result", "ok"]] }] }, "event"), []);
  assert.deepEqual(check({ v: 1, type: "session.state", workspace: "/w", workspace_name: "w", model: "m", mode: "review", git: null, busy: true }, "event"), []);
  assert.deepEqual(check({ v: 1, type: "checkpoint.choice", id: "c1", choice: "retry" }, "command"), []);
  // Capability negotiation: the hello a current sidecar sends, initialize with and without its optional fields, and the answer.
  assert.deepEqual(check({ v: 1, type: "hello", protocol: 1, pid: 42, commands: [], protocol_min: 1, protocol_max: 1, capabilities: [...SIDECAR_CAPABILITIES], experimental: [] }, "event"), []);
  assert.deepEqual(check({ v: 1, type: "initialize", id: "i1", client: { name: "c", version: "1" } }, "command"), []);
  assert.deepEqual(check({ v: 1, type: "initialize", id: "i1", client: { name: "c", version: "1" }, protocol_min: 1, protocol_max: 2, experimental: true }, "command"), []);
  assert.deepEqual(check({ v: 1, type: "initialized", id: "i1", protocol: 1, capabilities: ["steer"], experimental: [] }, "event"), []);
  assert.deepEqual(check({ v: 1, type: "error", id: "i1", code: "UNSUPPORTED_PROTOCOL", message: "m" }, "event"), []);
  assert.deepEqual(check({ v: 1, type: "error", code: "EXPERIMENTAL_DISABLED", message: "m" }, "event"), []);
  // Forward compatibility: a field a newer peer added is ignored, not rejected.
  assert.deepEqual(check({ v: 1, type: "assistant.delta", turn_id: "t1", text: "hi", added_later: 1 }, "event"), []);
});

test("the validator rejects messages the schema does not allow", () => {
  const rejected = (message: unknown, to: keyof typeof direction, reason: RegExp) => {
    const errors = check(message, to);
    assert.ok(errors.some((error) => reason.test(error)), `expected ${reason} in ${JSON.stringify(errors)}`);
  };
  rejected({ v: 1, type: "no.such.message" }, "event", /matches no oneOf alternative/);
  rejected({ v: 1, type: "no.such.message", id: "x" }, "command", /matches no oneOf alternative/);
  rejected({ v: 1, type: "assistant.delta", turn_id: "t1" }, "event", /missing required text/);
  rejected({ v: 1, type: "prompt.submit", text: "hi" }, "command", /missing required id/);
  rejected({ v: 1, type: "assistant.delta", turn_id: "t1", text: 7 }, "event", /\$\.text: expected string, got number/);
  rejected({ v: 1, type: "approve", id: "a1", always: "yes" }, "command", /\$\.always: expected boolean, got string/);
  rejected({ v: 1, type: "session.state", workspace: "/w", workspace_name: "w", model: "m", mode: "yolo", git: null, busy: true }, "event", /\$\.mode: not one of/);
  rejected({ v: 1, type: "receipt", id: "r1", sections: [{ title: "t", rows: [["only one"]] }] }, "event", /fewer than 2 items/);
  rejected({ v: 2, type: "shutdown" }, "command", /\$\.v: expected 1/);
  rejected({ v: 1, type: "initialize", id: "i1" }, "command", /missing required client/);
  rejected({ v: 1, type: "initialize", id: "i1", client: { name: "c" } }, "command", /missing required version/);
  rejected({ v: 1, type: "initialized", id: "i1", protocol: 1, capabilities: [] }, "event", /missing required experimental/);
  rejected({ v: 1, type: "hello", protocol: 1, pid: 1, commands: [], capabilities: "steer" }, "event", /\$\.capabilities: expected array/);
  rejected({ type: "shutdown" }, "command", /missing required v/);
  // A command of the same name does not pass as the event (tool.detail and receipt exist in both directions).
  rejected({ v: 1, type: "tool.detail", id: "d1", evidence: "e1" }, "event", /missing required/);
  assert.throws(() => validate(1, { minimum: 0 }), /unsupported schema keyword/);
});

test("parseCommand handles exactly the command variants the schema publishes", () => {
  const source = fs.readFileSync(fileURLToPath(new URL("../src/protocol.ts", import.meta.url)), "utf8");
  const start = source.indexOf("export function parseCommand(");
  const end = source.indexOf("\nexport function ", start + 1);
  assert.ok(start >= 0 && end > start, "parseCommand is in src/protocol.ts");
  const handled = [...source.slice(start, end).matchAll(/\bcase "([^"]+)":/g)].map((match) => match[1]).sort();
  assert.ok(handled.length > 0);
  assert.deepEqual(handled, variantTypes("SidecarCommand").sort());
  assert.ok(handled.includes("initialize"));
});

test("every announced capability is a published command type, and the list is sorted and unique", () => {
  const commands = variantTypes("SidecarCommand");
  for (const capability of SIDECAR_CAPABILITIES) assert.ok(commands.includes(capability), `${capability} is a command type`);
  assert.deepEqual([...SIDECAR_CAPABILITIES], [...new Set<string>(SIDECAR_CAPABILITIES)].sort());
  assert.ok(PROTOCOL_MIN <= PROTOCOL_VERSION && PROTOCOL_VERSION <= PROTOCOL_MAX, "the default version lies in the announced range");
  assert.deepEqual(EXPERIMENTAL_FEATURES, [], "no experimental feature is offered yet; the first one updates this");
});

test("message variants are told apart by a constant type and carry the wire version", () => {
  for (const name of ["SidecarEvent", "SidecarCommand"] as const) {
    const types = variantTypes(name);
    assert.equal(new Set(types).size, types.length, `${name} variant types are unique`);
    for (const variant of schema.$defs[name].oneOf) {
      assert.equal(typeof variant.properties.type.const, "string");
      assert.deepEqual(variant.properties.v, { const: PROTOCOL_VERSION });
      assert.ok(variant.required.includes("type") && variant.required.includes("v"));
      assert.notEqual(variant.additionalProperties, false, "messages stay open to fields added later");
    }
  }
});
import { test } from "node:test";
import * as assert from "node:assert/strict";
import fs from "node:fs";
import { fileURLToPath } from "node:url";
import { encodeEvent, parseCommand, PROTOCOL_VERSION } from "../src/protocol.js";
import type { SidecarEvent } from "../src/protocol.js";

// Shared with the Rust TUI test in core/src/bin/nexus_tui/protocol.rs. A change to either side's wire
// format must be accompanied by a deliberate corpus update, not discovered by a downstream consumer.
const corpusPath = fileURLToPath(new URL("./fixtures/protocol_v1_golden.jsonl", import.meta.url));
const records = fs.readFileSync(corpusPath, "utf8")
  .split(/\r?\n/)
  .filter(Boolean)
  .map((line, index) => ({ ...JSON.parse(line), index }));

test("protocol golden corpus is present and versioned", () => {
  assert.ok(records.length >= 8, "the golden corpus must cover both directions of the v1 protocol");
  for (const record of records) {
    const value = JSON.parse(record.json);
    assert.equal(value.v, PROTOCOL_VERSION, `record ${record.index} must be protocol v${PROTOCOL_VERSION}`);
    assert.equal(value.type, record.name, `record ${record.index} type must match its corpus name`);
    assert.ok(["event", "command"].includes(record.direction), `record ${record.index} has a known direction`);
  }
});

test("the golden corpus covers capability negotiation in both directions", () => {
  const named = (direction: string, name: string) => records.filter((r) => r.direction === direction && r.name === name).map((r) => JSON.parse(r.json));
  const hellos = named("event", "hello");
  assert.ok(hellos.some((hello) => hello.protocol_min === undefined), "a hello from a sidecar older than negotiation stays in the corpus");
  const hello = hellos.find((h) => h.protocol_min !== undefined);
  assert.ok(hello, "a hello with the negotiation fields");
  assert.ok(Number.isInteger(hello.protocol_min) && Number.isInteger(hello.protocol_max) && hello.protocol_min <= hello.protocol && hello.protocol <= hello.protocol_max);
  assert.ok(Array.isArray(hello.capabilities) && Array.isArray(hello.experimental));
  assert.equal(named("command", "initialize").length, 1);
  const [initialized] = named("event", "initialized");
  assert.ok(initialized && Array.isArray(initialized.capabilities) && Array.isArray(initialized.experimental));
});

test("sidecar events in the golden corpus encode to exactly the recorded wire shape", () => {
  for (const record of records.filter((r) => r.direction === "event")) {
    const { v: _version, ...event } = JSON.parse(record.json);
    const line = encodeEvent(event as SidecarEvent);
    assert.ok(line.endsWith("\n"), `${record.name} encodes as one NDJSON line`);
    assert.equal(line.indexOf("\n"), line.length - 1, `${record.name} has no embedded raw newline`);
    assert.deepEqual(JSON.parse(line), { v: PROTOCOL_VERSION, ...event }, `${record.name} wire shape`);
  }
});

test("Rust TUI commands in the golden corpus parse to exactly the recorded values", () => {
  for (const record of records.filter((r) => r.direction === "command")) {
    const { v: _version, ...expected } = JSON.parse(record.json);
    assert.deepEqual(parseCommand(record.json), expected, `${record.name} parsed command`);
  }
});
/**
 * Capability negotiation (PF-1): what `hello` announces, how `initialize` is answered, and the gate experimental
 * features sit behind. A client that never sends `initialize` is the subject of every other sidecar test file.
 */
import { test, describe } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import "./helpers/leak_guard.js";
import { ApplicationCore } from "../src/core/app.js";
import { SidecarOptions, SidecarServer } from "../src/sidecar.js";
import { EXPERIMENTAL_FEATURES, PROTOCOL_MAX, PROTOCOL_MIN, PROTOCOL_VERSION, SIDECAR_CAPABILITIES } from "../src/protocol.js";
import { slashCatalog } from "../src/slash/catalog.js";
import { startGateway, makeRepo, makeHome, waitForEvent, Reply } from "./helpers/fixtures.js";

interface Rig {
  server: SidecarServer;
  events: any[];
  send(msg: Record<string, unknown>): Promise<void>;
}

const CLIENT = { name: "test-client", version: "0.0.1" };

async function withSidecar(fn: (rig: Rig) => Promise<void>, options: Partial<SidecarOptions> = {}, script: (n: number) => Reply = () => ({ kind: "text", content: "Done." })): Promise<void> {
  const gw = await startGateway(script);
  const repo = makeRepo();
  const home = makeHome();
  const previousHome = process.env.HOME;
  process.env.HOME = home;
  const app = new ApplicationCore({ endpoint: gw.url, model: "m", maxSteps: 6, temperature: 0, workspace: repo, shell: "bash", approvalMode: "auto", fullAccess: true } as any);
  const events: any[] = [];
  const server = new SidecarServer({ app, mode: "auto", write: (line) => events.push(JSON.parse(line)), ...options });
  server.start();
  try {
    await fn({ server, events, send: (msg) => server.handleLine(JSON.stringify({ v: 1, ...msg })) });
  } finally {
    await server.handleLine(JSON.stringify({ v: 1, type: "cancel" }));
    await server.idle();
    app.shutdown();
    await gw.close();
    if (previousHome === undefined) delete process.env.HOME;
    else process.env.HOME = previousHome;
    fs.rmSync(repo, { recursive: true, force: true });
    fs.rmSync(home, { recursive: true, force: true });
  }
}

describe("SidecarServer: capability negotiation", () => {
  test("hello announces the version range, the stable capabilities and the experimental features on offer", async () => {
    await withSidecar(async ({ events }) => {
      assert.deepEqual(events[0], {
        v: 1, type: "hello", protocol: PROTOCOL_VERSION, pid: process.pid, commands: slashCatalog(),
        protocol_min: PROTOCOL_MIN, protocol_max: PROTOCOL_MAX, capabilities: [...SIDECAR_CAPABILITIES], experimental: [],
      });
      assert.deepEqual(events[0].capabilities, [...events[0].capabilities].sort(), "capabilities are sorted");
      assert.deepEqual([PROTOCOL_MIN, PROTOCOL_MAX], [1, 1]);
      assert.deepEqual(EXPERIMENTAL_FEATURES, []);
    });
    await withSidecar(async ({ events }) => {
      assert.deepEqual(events[0].experimental, ["a.test", "x.test"], "an injected list is announced sorted, without duplicates");
    }, { experimentalFeatures: ["x.test", "a.test", "x.test"] });
  });

  test("initialize with an overlapping range is answered with the highest common version", async () => {
    await withSidecar(async ({ events, send }) => {
      await send({ type: "initialize", id: "i1", client: CLIENT, protocol_min: 1, protocol_max: 4 });
      assert.deepEqual(events.at(-1), { v: 1, type: "initialized", id: "i1", protocol: PROTOCOL_MAX, capabilities: [...SIDECAR_CAPABILITIES], experimental: [] });
    });
    // No range: the version of the message itself.
    await withSidecar(async ({ events, send }) => {
      await send({ type: "initialize", id: "i2", client: CLIENT });
      assert.deepEqual(events.at(-1), { v: 1, type: "initialized", id: "i2", protocol: 1, capabilities: [...SIDECAR_CAPABILITIES], experimental: [] });
    });
  });

  test("a range with no common version blocks commands until a compatible initialize retry", async () => {
    await withSidecar(async ({ server, events, send }) => {
      await send({ type: "initialize", id: "i1", client: CLIENT, protocol_min: 2, protocol_max: 3 });
      assert.deepEqual(events.at(-1), {
        v: 1, type: "error", id: "i1", code: "UNSUPPORTED_PROTOCOL",
        message: `No common protocol version: the client speaks 2 to 3, this sidecar speaks ${PROTOCOL_MIN} to ${PROTOCOL_MAX}.`,
      });
      assert.equal(events.some((e) => e.type === "initialized"), false);
      // The client cannot fall back to the bootstrap version after declaring that it cannot speak it.
      await send({ type: "receipt", id: "r1" });
      assert.deepEqual(events.at(-1), {
        v: 1, type: "error", id: "r1", code: "UNSUPPORTED_PROTOCOL",
        message: `No common protocol version: the client speaks 2 to 3, this sidecar speaks ${PROTOCOL_MIN} to ${PROTOCOL_MAX}.`,
      });
      await send({ type: "prompt.submit", id: "t1", text: "say done" });
      await server.idle();
      assert.equal(events.some((e) => e.type === "turn.result" && e.turn_id === "t1"), false, "no prompt runs under an unsupported protocol");
      // A compatible retry unblocks the connection.
      await send({ type: "initialize", id: "i2", client: CLIENT, protocol_min: 1, protocol_max: 3 });
      assert.deepEqual(events.at(-1), { v: 1, type: "initialized", id: "i2", protocol: 1, capabilities: [...SIDECAR_CAPABILITIES], experimental: [] });
      await send({ type: "prompt.submit", id: "t2", text: "say done" });
      await server.idle();
      assert.equal(events.find((e) => e.type === "turn.result" && e.turn_id === "t2")?.turn_id, "t2");
    });
  });

  test("a second initialize is BAD_REQUEST and leaves the first negotiation in force", async () => {
    await withSidecar(async ({ server, events, send }) => {
      await send({ type: "initialize", id: "i1", client: CLIENT });
      await send({ type: "initialize", id: "i2", client: CLIENT, experimental: true });
      const refusal = events.at(-1);
      assert.deepEqual({ type: refusal.type, id: refusal.id, code: refusal.code }, { type: "error", id: "i2", code: "BAD_REQUEST" });
      assert.match(refusal.message, /already answered on this connection \(protocol 1\)/);
      assert.equal(events.filter((e) => e.type === "initialized").length, 1);
      assert.equal(server.requireExperimental("x.test", "g1"), false, "the refused initialize enabled nothing");
    }, { experimentalFeatures: ["x.test"] });
  });

  test("a malformed initialize is BAD_REQUEST and does not use up the connection's one negotiation", async () => {
    await withSidecar(async ({ events, send }) => {
      await send({ type: "initialize", id: "i1", client: { name: "c" } });
      assert.deepEqual(events.at(-1), { v: 1, type: "error", id: "i1", code: "BAD_REQUEST", message: "initialize requires client.version: a non-empty string" });
      await send({ type: "initialize", id: "i2", client: CLIENT, protocol_min: 3, protocol_max: 2 });
      assert.equal(events.at(-1).code, "BAD_REQUEST");
      await send({ type: "initialize", id: "i3", client: CLIENT });
      assert.equal(events.at(-1).type, "initialized");
    });
  });

  test("initialize is answered while a turn is running and does not disturb it", async () => {
    await withSidecar(async ({ server, events, send }) => {
      await send({ type: "prompt.submit", id: "t1", text: "work" });
      await waitForEvent(events, (e) => e.type === "session.state" && e.busy === true);
      await send({ type: "initialize", id: "i1", client: CLIENT });
      assert.equal(events.at(-1).type, "initialized");
      assert.equal(events.some((e) => e.type === "turn.result"), false, "the turn is still running");
      await server.idle();
      assert.equal(events.find((e) => e.type === "turn.result")?.turn.execution, "COMPLETED");
    }, {}, () => ({ kind: "text", content: "Done.", delayMs: 1500 }));
  });

  test("an old client that never sends initialize gets a turn exactly as before, and no negotiation event", async () => {
    await withSidecar(async ({ server, events, send }) => {
      await send({ type: "prompt.submit", id: "t1", text: "say done" });
      await server.idle();
      assert.equal(events.find((e) => e.type === "turn.result")?.turn.execution, "COMPLETED");
      assert.equal(events.some((e) => e.type === "initialized" || e.type === "error"), false);
      for (const e of events) assert.equal(e.v, 1);
    }, { experimentalFeatures: ["x.test"] });
  });
});

describe("SidecarServer: the experimental gate", () => {
  // "x.test" is registered through the test-only option; no product feature is experimental yet.
  const offered = { experimentalFeatures: ["x.test"] };

  test("an experimental feature is refused with EXPERIMENTAL_DISABLED until initialize asks for experimental", async () => {
    await withSidecar(async ({ server, events, send }) => {
      assert.equal(server.requireExperimental("x.test", "g1"), false);
      assert.deepEqual(events.at(-1), { v: 1, type: "error", id: "g1", code: "EXPERIMENTAL_DISABLED", message: "x.test is experimental: send initialize with experimental: true before using it." });
      await send({ type: "initialize", id: "i1", client: CLIENT, experimental: true });
      assert.deepEqual(events.at(-1), { v: 1, type: "initialized", id: "i1", protocol: 1, capabilities: [...SIDECAR_CAPABILITIES], experimental: ["x.test"] });
      const before = events.length;
      assert.equal(server.requireExperimental("x.test", "g2"), true);
      assert.equal(events.length, before, "an enabled feature passes the gate silently");
      // A name this sidecar does not offer stays refused, enabled connection or not; without an id the error carries none.
      assert.equal(server.requireExperimental("y.test"), false);
      assert.deepEqual(events.at(-1), { v: 1, type: "error", code: "EXPERIMENTAL_DISABLED", message: "y.test is not an experimental feature this sidecar offers." });
    }, offered);
  });

  test("initialize without experimental: true enables nothing", async () => {
    for (const experimental of [undefined, false]) {
      await withSidecar(async ({ server, events, send }) => {
        await send({ type: "initialize", id: "i1", client: CLIENT, ...(experimental === undefined ? {} : { experimental }) });
        assert.deepEqual(events.at(-1).experimental, []);
        assert.equal(server.requireExperimental("x.test", "g1"), false);
        assert.equal(events.at(-1).code, "EXPERIMENTAL_DISABLED");
      }, offered);
    }
  });
});
// A small JSON Schema validator for the subset scripts/gen_protocol_schema.mjs emits (draft 2020-12 keywords: type,
// const, enum, properties, required, additionalProperties, items, prefixItems, minItems, maxItems, anyOf, oneOf and a
// local $ref). It is a test helper, not a general validator: a keyword outside that subset throws, so a generator that
// starts emitting a new keyword cannot pass unvalidated.
import { isDeepStrictEqual } from "node:util";

export type Schema = Record<string, any>;

const ANNOTATIONS = new Set(["$schema", "$defs", "title", "description"]);
const KEYWORDS = new Set(["$ref", "type", "const", "enum", "properties", "required", "additionalProperties", "items", "prefixItems", "minItems", "maxItems", "anyOf", "oneOf"]);

function typeName(value: unknown): string {
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  return typeof value;
}

function resolve(root: Schema, ref: string): Schema {
  if (!ref.startsWith("#/")) throw new Error(`unsupported $ref: ${ref}`);
  let node: any = root;
  for (const part of ref.slice(2).split("/")) node = node?.[part.replace(/~1/g, "/").replace(/~0/g, "~")];
  if (!node || typeof node !== "object") throw new Error(`unresolved $ref: ${ref}`);
  return node;
}

/** Every way `value` fails `schema`, as `path: reason` lines; empty when it is valid. `root` resolves `$ref`. */
export function validate(value: unknown, schema: Schema, root: Schema = schema, at = "$"): string[] {
  for (const keyword of Object.keys(schema)) {
    if (!KEYWORDS.has(keyword) && !ANNOTATIONS.has(keyword)) throw new Error(`unsupported schema keyword at ${at}: ${keyword}`);
  }
  const errors: string[] = [];
  if (schema.$ref) errors.push(...validate(value, resolve(root, schema.$ref), root, at));
  const actual = typeName(value);
  if (schema.type !== undefined && actual !== schema.type) errors.push(`${at}: expected ${schema.type}, got ${actual}`);
  if ("const" in schema && !isDeepStrictEqual(value, schema.const)) errors.push(`${at}: expected ${JSON.stringify(schema.const)}`);
  if (schema.enum && !schema.enum.some((allowed: unknown) => isDeepStrictEqual(value, allowed))) errors.push(`${at}: not one of ${JSON.stringify(schema.enum)}`);

  if (actual === "object") {
    const object = value as Record<string, unknown>;
    const properties: Record<string, Schema> = schema.properties ?? {};
    for (const name of schema.required ?? []) {
      if (!Object.hasOwn(object, name)) errors.push(`${at}: missing required ${name}`);
    }
    for (const [name, member] of Object.entries(object)) {
      if (Object.hasOwn(properties, name)) errors.push(...validate(member, properties[name], root, `${at}.${name}`));
      else if (schema.additionalProperties === false) errors.push(`${at}: unexpected property ${name}`);
      else if (typeof schema.additionalProperties === "object") errors.push(...validate(member, schema.additionalProperties, root, `${at}.${name}`));
    }
  }

  if (actual === "array") {
    const array = value as unknown[];
    const prefix: Schema[] = schema.prefixItems ?? [];
    if (schema.minItems !== undefined && array.length < schema.minItems) errors.push(`${at}: fewer than ${schema.minItems} items`);
    if (schema.maxItems !== undefined && array.length > schema.maxItems) errors.push(`${at}: more than ${schema.maxItems} items`);
    array.forEach((item, i) => {
      if (i < prefix.length) errors.push(...validate(item, prefix[i], root, `${at}[${i}]`));
      else if (schema.items) errors.push(...validate(item, schema.items, root, `${at}[${i}]`));
    });
  }

  for (const keyword of ["anyOf", "oneOf"] as const) {
    if (!schema[keyword]) continue;
    const results: string[][] = schema[keyword].map((option: Schema) => validate(value, option, root, at));
    const matches = results.filter((result) => result.length === 0).length;
    if (matches === 1 || (matches > 1 && keyword === "anyOf")) continue;
    if (matches > 1) {
      errors.push(`${at}: matches ${matches} oneOf alternatives`);
      continue;
    }
    // Explain with the alternative that came closest. For a message union that is the variant whose `type` matched;
    // when no variant's did, the type is unknown and there is nothing more to say.
    const candidates = results.filter((result) => !result.some((error) => error.startsWith(`${at}.type:`)));
    const closest = candidates.reduce<string[]>((best, result) => (best.length === 0 || result.length < best.length ? result : best), []);
    errors.push(`${at}: matches no ${keyword} alternative`, ...closest);
  }
  return errors;
}
// Transparent sidecar shim for `nexus-tui --live --sidecar <this file>`: runs the real sidecar named by
// NEXUS_RECORD_SIDECAR and appends every raw stdin chunk to NEXUS_RECORD_COMMANDS and every raw stdout chunk to
// NEXUS_RECORD_EVENTS. It never parses, filters or rewrites bytes. Appends are synchronous so both logs are
// complete when the process exits.
import { spawn } from "node:child_process";
import fs from "node:fs";

const commandsLog = process.env.NEXUS_RECORD_COMMANDS;
const eventsLog = process.env.NEXUS_RECORD_EVENTS;

const child = spawn(process.execPath, [process.env.NEXUS_RECORD_SIDECAR, ...process.argv.slice(2)], {
  stdio: ["pipe", "pipe", "inherit"],
});

process.stdin.on("data", (chunk) => {
  fs.appendFileSync(commandsLog, chunk);
  child.stdin.write(chunk);
});
process.stdin.on("end", () => child.stdin.end());
child.stdin.on("error", () => {});
process.stdout.on("error", () => {});

child.stdout.on("data", (chunk) => {
  fs.appendFileSync(eventsLog, chunk);
  process.stdout.write(chunk);
});

for (const signal of ["SIGTERM", "SIGINT", "SIGHUP"]) {
  process.on(signal, () => child.kill(signal));
}

child.on("close", (code) => {
  process.exit(code ?? 1);
});
